def min_operations(n, nums):
    max_value = max(nums)
    freq = [0] * (max_value + 1)
    for x in nums:
        freq[x] += 1

    is_prime = [True] * (max_value + 1)
    if max_value >= 0:
        is_prime[0] = False
    if max_value >= 1:
        is_prime[1] = False

    i = 2
    while i * i <= max_value:
        if is_prime[i]:
            for j in range(i * i, max_value + 1, i):
                is_prime[j] = False
        i += 1

    max_count = 0
    for p in range(2, max_value + 1):
        if is_prime[p]:
            count = 0
            for multiple in range(p, max_value + 1, p):
                count += freq[multiple]
            if count > max_count:
                max_count = count

    return n - max_count

def main():
    import sys
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    nums = data[1:1+n]
    print(min_operations(n, nums))

